## Proposed file

Target: `tests/contract/http/orders_idempotency_test.go`

```go
package httpcontract_test

import (
	"bytes"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

const (
	// The fixture identifies the idempotency key but not its HTTP header name.
	// Replace this proposed conventional name if the frozen contract differs.
	idempotencyHeaderName = "Idempotency-Key"

	// The fixture identifies the command ID value but not its JSON field name.
	// Replace this proposed camel-case name if the frozen contract differs.
	commandIDFieldName = "commandId"
)

// TestOrdersHTTP_IdempotentCreateAndKeyReuse ports the supplied order-create
// compatibility behavior.
//
// Ported from:
//   repository: <UNAVAILABLE_SOURCE_REPOSITORY>@<UNAVAILABLE_SOURCE_REVISION>
//   source: <UNAVAILABLE_SOURCE_PATH>:<UNAVAILABLE_SOURCE_LINE>
//   test: <UNAVAILABLE_SOURCE_TEST_FUNCTION>
//
// Adaptations:
//   - The source HTTP request is expressed with httptest.
//   - Decimal quantities remain exact JSON strings.
//   - Sequential calls make retry ordering explicit.
//   - Response bytes are retained for exact replay comparison.
//
// Assertions preserved:
//   - POST /v1/orders with key "same-key" and quantity "0.0100" returns 201.
//   - The response quantity is exactly "0.0100".
//   - The response contains stopLoss with the JSON value null.
//   - The response command ID is "cmd-7".
//   - An identical retry returns the same status and byte-equivalent body.
//   - Reusing the key with quantity "0.0200" returns 409.
//   - The conflict error code is IDEMPOTENCY_KEY_REUSED.
func TestOrdersHTTP_IdempotentCreateAndKeyReuse(t *testing.T) {
	handler := newOrdersContractHandler(t)

	firstRequest := []byte(`{"quantity":"0.0100"}`)
	requireJSONFieldOmitted(t, firstRequest, "stopLoss")

	first := performOrderRequest(t, handler, "same-key", firstRequest)
	if first.status != http.StatusCreated {
		t.Fatalf("first response status = %d, want %d; body=%s",
			first.status, http.StatusCreated, first.body)
	}

	firstJSON := decodeJSONObject(t, first.body)
	requireJSONString(t, firstJSON, "quantity", "0.0100")
	requireJSONNull(t, firstJSON, "stopLoss")
	requireJSONString(t, firstJSON, commandIDFieldName, "cmd-7")

	retry := performOrderRequest(t, handler, "same-key", firstRequest)
	if retry.status != first.status {
		t.Fatalf("retry status = %d, want original status %d",
			retry.status, first.status)
	}
	if !bytes.Equal(retry.body, first.body) {
		t.Fatalf(
			"retry body is not byte-equivalent to original:\noriginal: %q\nretry:    %q",
			first.body,
			retry.body,
		)
	}

	changedRequest := []byte(`{"quantity":"0.0200"}`)
	requireJSONFieldOmitted(t, changedRequest, "stopLoss")

	conflict := performOrderRequest(t, handler, "same-key", changedRequest)
	if conflict.status != http.StatusConflict {
		t.Fatalf("key-reuse response status = %d, want %d; body=%s",
			conflict.status, http.StatusConflict, conflict.body)
	}

	conflictJSON := decodeJSONObject(t, conflict.body)
	requireJSONString(
		t,
		conflictJSON,
		"code",
		"IDEMPOTENCY_KEY_REUSED",
	)
}

type recordedResponse struct {
	status int
	body   []byte
}

func performOrderRequest(
	t *testing.T,
	handler http.Handler,
	idempotencyKey string,
	body []byte,
) recordedResponse {
	t.Helper()

	request := httptest.NewRequest(
		http.MethodPost,
		"/v1/orders",
		bytes.NewReader(body),
	)
	request.Header.Set("Content-Type", "application/json")
	request.Header.Set(idempotencyHeaderName, idempotencyKey)

	recorder := httptest.NewRecorder()
	handler.ServeHTTP(recorder, request)

	response := recorder.Result()
	defer response.Body.Close()

	responseBody, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatalf("read response body: %v", err)
	}

	return recordedResponse{
		status: response.StatusCode,
		body:   responseBody,
	}
}

func decodeJSONObject(t *testing.T, body []byte) map[string]json.RawMessage {
	t.Helper()

	var object map[string]json.RawMessage
	if err := json.Unmarshal(body, &object); err != nil {
		t.Fatalf("decode JSON object %q: %v", body, err)
	}
	if object == nil {
		t.Fatalf("response %q is not a JSON object", body)
	}

	return object
}

func requireJSONString(
	t *testing.T,
	object map[string]json.RawMessage,
	field string,
	want string,
) {
	t.Helper()

	raw, exists := object[field]
	if !exists {
		t.Fatalf("JSON field %q is omitted, want string %q", field, want)
	}

	var got string
	if err := json.Unmarshal(raw, &got); err != nil {
		t.Fatalf("JSON field %q = %s, want string %q: %v",
			field, raw, want, err)
	}
	if got != want {
		t.Fatalf("JSON field %q = %q, want %q", field, got, want)
	}
}

func requireJSONNull(
	t *testing.T,
	object map[string]json.RawMessage,
	field string,
) {
	t.Helper()

	raw, exists := object[field]
	if !exists {
		t.Fatalf("JSON field %q is omitted, want explicit null", field)
	}
	if !bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		t.Fatalf("JSON field %q = %s, want null", field, raw)
	}
}

func requireJSONFieldOmitted(t *testing.T, body []byte, field string) {
	t.Helper()

	object := decodeJSONObject(t, body)
	if raw, exists := object[field]; exists {
		t.Fatalf("request JSON field %q = %s, want omitted", field, raw)
	}
}

// newOrdersContractHandler is the only repository-specific binding required by
// this test. Replace this body with the existing production HTTP composition,
// including the deterministic authenticated principal required by that
// composition.
func newOrdersContractHandler(t *testing.T) http.Handler {
	t.Helper()
	t.Fatal(
		"bind the repository's production POST /v1/orders handler; " +
			"the constructor and authentication fixture were not supplied",
	)
	return nil
}
```

